// 1. Lay output cua LLM - chainLlm tra ve field 'output'
const inp = $input.first().json;
const llmRaw = inp.output || inp.text || inp.response || inp.content || '';

// 2. Parse JSON tu LLM output - GREEDY regex de bat toan bo JSON ke ca nested
let intent = { apiCode: null, params: {}, isComplex: false };
try {
  const m = llmRaw.match(/{[\s\S]*}/);
  if (m) intent = JSON.parse(m[0]);
} catch(e) {
  intent = { apiCode: null, params: {}, isComplex: true };
}

// 3. Decode JWT lay username
let username = 'demo';
try {
  const authHeader = $('Webhook AI Chat').first().json.headers?.authorization || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();
  if (token && token.split('.').length === 3) {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString('utf-8'));
    username = payload.Username || payload.username || payload.sub || 'demo';
  }
} catch(e) { username = 'demo'; }

// 4. Inject @Username vao params
if (intent.apiCode) {
  intent.params = Object.assign({}, intent.params, { '@Username': username });
}

// 5. Replace date placeholders
const now = new Date();
const today = now.toISOString().split('T')[0];
const monthStart = today.substring(0, 7) + '-01';
const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0).toISOString().split('T')[0];

// Previous month
const prevMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const prevMonthStart = prevMonthDate.toISOString().split('T')[0].substring(0, 7) + '-01';
const prevMonthEnd = new Date(now.getFullYear(), now.getMonth(), 0).toISOString().split('T')[0];

const placeholders = {
  '[TODAY]': today,
  '[MONTH_START]': monthStart,
  '[MONTH_END]': monthEnd,
  '[PREV_MONTH_START]': prevMonthStart,
  '[PREV_MONTH_END]': prevMonthEnd,
  '[MONTH_START_PREV]': prevMonthStart,
  '[MONTH_END_PREV]': prevMonthEnd,
  '[LAST_MONTH_START]': prevMonthStart,
  '[LAST_MONTH_END]': prevMonthEnd
};

for (const k of Object.keys(intent.params || {})) {
  const v = intent.params[k];
  if (typeof v === 'string' && placeholders[v]) {
    intent.params[k] = placeholders[v];
  }
}

const isValid = !!intent.apiCode && !intent.isComplex;
return [{ json: {
  apiCode: intent.apiCode,
  params: intent.params || {},
  isComplex: !!intent.isComplex,
  username: username,
  isValid: isValid,
  _debug_llm: llmRaw.substring(0, 300)
} }];

const k0 = $input.first()?.json || {};
const status = k0.status || 'success';
const count = k0.count || 0;
const data = k0.data || [];
const apiCode = $('Parse Intent & Auth').first().json.apiCode || '';

let message = '';
if (status === 'error') {
  message = k0.reply || k0.message || 'Co loi xay ra';
  return [{ json: { status: 'error', message: message, data: [], count: 0, apiCode: apiCode } }];
}

if (count === 0 || data.length === 0) {
  message = 'Khong tim thay du lieu phu hop.';
  return [{ json: { status: 'success', message: message, data: [], count: 0, apiCode: apiCode } }];
}

message = k0.reply || ('Tim thay ' + count + ' ket qua.');
return [{ json: {
  status: 'success',
  message: message,
  data: data,
  count: count,
  apiCode: apiCode
} }];
